sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float yaw;
uniform float pitch;
uniform float roll;
uniform float fov;
uniform float projection;
uniform float eyeDistance;
uniform float frame;
float3 turn(float3 d) {
    float y = radians(yaw);
    float p = radians(pitch);
    float r = radians(roll);
    d = float3(cos(r) * d.x - sin(r) * d.y, sin(r) * d.x + cos(r) * d.y, d.z);
    d = float3(d.x, cos(p) * d.y - sin(p) * d.z, sin(p) * d.y + cos(p) * d.z);
    return float3(cos(y) * d.x + sin(y) * d.z, d.y, -sin(y) * d.x + cos(y) * d.z);
}
half4 panorama(float3 d) {
    float lon = atan(d.x, d.z);
    float lat = asin(clamp(d.y, -1.0, 1.0));
    float2 uv = float2(lon / 6.2831853 + 0.5, 0.5 - lat / 3.1415927);
    float2 at = float2(mod(uv.x * size.x, size.x), clamp(uv.y * size.y, 0.5, size.y - 0.5));
    return image.eval(clamp(at, float2(0.5), size - 0.5));
}
half4 main(float2 coord) {
    if (coord.x < 0.0 || coord.y < 0.0 || coord.x > size.x || coord.y > size.y) return half4(0.0);
    if (projection > 0.5) {
        float2 uv = coord / size;
        float lon = (uv.x - 0.5) * 6.2831853;
        float lat = (0.5 - uv.y) * 3.1415927;
        return panorama(turn(float3(cos(lat) * sin(lon), sin(lat), cos(lat) * cos(lon))));
    }
    float2 ndc = (coord - size * 0.5) / (0.5 * size.y);
    if (frame > 0.0) {
        float2 box = size.x > size.y * frame ? float2(size.y * frame, size.y) : float2(size.x, size.x / frame);
        if (abs(ndc.x) * size.y > box.x || abs(ndc.y) * size.y > box.y) return half4(0.0);
        ndc *= size.y / box.x;
    }
    float k = tan(radians(clamp(fov, 1.0, 179.0)) * 0.5);
    float3 d = normalize(float3(ndc.x * k, -ndc.y * k, 1.0));
    if (eyeDistance > 0.0) {
        float b = -eyeDistance * d.z;
        float t = -b + sqrt(max(b * b - eyeDistance * eyeDistance + 1.0, 0.0));
        d = normalize(float3(0.0, 0.0, -eyeDistance) + d * t);
    }
    return panorama(turn(d));
}
